import sys
from functools import lru_cache

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    l_str = input_data[0]
    r_str = input_data[1]
    n = int(input_data[2])

    l_val = int(l_str)
    r_val = int(r_str)

    len_l = len(l_str)
    len_r = len(r_str)

    def get_bounds(length):
        if length < len_l:
            return None, None
        if length > len_r:
            return None, None
        if length == len_l and length == len_r:
            return l_str, r_str
        if length == len_l:
            return l_str, "9" * length
        if length == len_r:
            return "0" * (length - 1) + "1", r_str
        return "0" * (length - 1) + "1", "9" * length

    memo_count = {}

    def count_valid(length, start_s, end_s):
        if length == 0:
            return 0
        key = (length, start_s, end_s)
        if key in memo_count:
            return memo_count[key]

        if start_s is None:
            low = 0
        else:
            low = int(start_s)
        if end_s is None:
            high = 10**length - 1
        else:
            high = int(end_s)

        if low > high:
            res = 0
        else:
            res = high - low + 1

        memo_count[key] = res
        return res

    def count_in_range(length):
        s, e = get_bounds(length)
        if s is None:
            return 0
        return count_valid(length, s, e)

    total_possible = 0
    for length in range(1, n + 1):
        total_possible += count_in_range(length)

    if total_possible == 0:
        print(0)
        print("0" * n)
        return

    best_score = -1
    best_string = None

    dp = [(-1, "")] * (n + 1)
    dp[0] = (0, "")

    for i in range(n):
        if dp[i][0] == -1:
            continue
        current_score, current_str = dp[i]

        for digit in "0123456789":
            new_str = current_str + digit
            if len(new_str) > n:
                break

            add_score = 0
            for length in range(1, len(new_str) + 1):
                suffix = new_str[-length:]
                if suffix[0] == '0' and length > 1:
                    continue
                s, e = get_bounds(length)
                if s is None:
                    continue
                num = int(suffix)
                if int(s) <= num <= int(e):
                    add_score += 1

            new_score = current_score + add_score
            pos = len(new_str)

            if new_score > dp[pos][0]:
                dp[pos] = (new_score, new_str)
            elif new_score == dp[pos][0]:
                if new_str < dp[pos][1]:
                    dp[pos] = (new_score, new_str)

    final_score, final_string = dp[n]

    print(final_score)
    print(final_string)

if __name__ == "__main__":
    solve()
